"""Reference-led organizer/camera, and a satin ceramic PBR sample. Pure SVG."""
import math, random
REVISIONS = {}
def add(key, description, defs, body):
    REVISIONS[key] = (description, defs, body)

folder_defs = '''<linearGradient id="folder-case" x2=".9" y2="1"><stop stop-color="#5488b5"/><stop offset=".2" stop-color="#355c89"/><stop offset="1" stop-color="#243d64"/></linearGradient><linearGradient id="folder-front" x2=".2" y2="1"><stop stop-color="#4983b6"/><stop offset=".5" stop-color="#326498"/><stop offset="1" stop-color="#244b78"/></linearGradient><linearGradient id="folder-inside" x2="1" y2="1"><stop stop-color="#102941"/><stop offset="1" stop-color="#366388"/></linearGradient><linearGradient id="folder-paper" x2=".3" y2="1"><stop stop-color="#fffef0"/><stop offset="1" stop-color="#b8c1ba"/></linearGradient>'''
for name, top, bottom in [('teal','#62cbb3','#218573'),('orange','#f6b16a','#c7732c'),('purple','#ce6ab6','#91377c'),('yellow','#f3d85d','#c7a72b')]:
    folder_defs += f'<linearGradient id="folder-{name}" x2=".35" y2="1"><stop stop-color="{top}"/><stop offset="1" stop-color="{bottom}"/></linearGradient>'
folder_defs += '<clipPath id="folder-content"><path d="M40 16H234V190L110 227 40 180Z"/></clipPath>'
folder_body = '''<path d="M30 76q-5-9 6-13l137-39q14-4 22 8l19 30v105L83 208 30 177Z" fill="url(#folder-case)"/><path d="m40 72 135-39q9-3 15 7l15 24v96L86 196 40 168Z" fill="url(#folder-inside)"/><path d="m39 68 136-40q12-3 19 10" stroke="#97b8d0" stroke-opacity=".36" stroke-width="2"/>'''
folder_body += '<g clip-path="url(#folder-content)">'
for i, name in enumerate(['teal','orange','purple','yellow']):
    dx,dy=i*12,i*21
    folder_body+=f'''<g transform="translate({dx} {dy})"><path d="M50 70V53q0-5 5-7l33-9q7-2 8 5l2 5 73-21q7-2 7 6v111L50 179Z" fill="url(#folder-{name})" stroke="#f7ffea" stroke-opacity=".18" stroke-width="1.1"/><path d="m56 72 117-34v98L56 170Z" fill="url(#folder-paper)"/><path d="m58 74 113-32m-113 35 113-32m-113 35 113-32" stroke="#9caaa7" stroke-opacity=".5" stroke-width=".75"/><path d="M54 89q0-7 7-9l36-10q5-2 9-8l4-7 67-19q6-2 6 5v103L54 181Z" fill="url(#folder-{name})"/><path d="M58 84 99 72q7-3 12-12l66-19" stroke="#ffffde" stroke-opacity=".3" stroke-width="1.2"/></g>'''
folder_body+='</g>'
folder_body+='''<path d="M29 73q17 4 29 27l31 62q6 12 21 14l10 43-10 16q-8 1-17-5l-56-36q-9-6-9-17V81q0-5 1-8Z" fill="url(#folder-case)"/><path d="M99 177q12 4 23-1l14-4q8-2 12 9l3 8q3 8 12 5l30-9q10-3 14-14l7-17q3-8 13-10l7-2v57q0 11-10 14l-108 32q-16 4-17-10Z" fill="url(#folder-front)"/><path d="M30 75q17 6 29 29l31 61q5 10 16 13t29-5q8-2 12 10l4 8q3 6 12 3l30-9q10-3 14-14l7-17q3-8 18-11" stroke="#84b2cf" stroke-opacity=".5" stroke-width="2.1" stroke-linecap="round"/><path d="M111 234 222 202" stroke="#102b4d" stroke-opacity=".3" stroke-width="1.2"/>'''
# Leave breathing room at the base and preserve the reference's compact silhouette.
add('folder','A blue desktop organizer with four colored tabbed folders and layered paper inserts, inspired by the supplied reference.',folder_defs,'<g transform="translate(4 0) scale(.96)">'+folder_body+'</g>')

camera_defs='''<linearGradient id="camera-body" x2=".1" y2="1"><stop stop-color="#55555e"/><stop offset=".35" stop-color="#34353c"/><stop offset="1" stop-color="#202126"/></linearGradient><linearGradient id="camera-edge" x2="0" y2="1"><stop stop-color="#9696a3" stop-opacity=".55"/><stop offset=".5" stop-color="#62626b" stop-opacity=".15"/><stop offset="1" stop-color="#08090c" stop-opacity=".8"/></linearGradient><linearGradient id="camera-ring" x2=".25" y2="1"><stop stop-color="#25262e"/><stop offset=".55" stop-color="#36373f"/><stop offset="1" stop-color="#676773"/></linearGradient><radialGradient id="camera-glass" cx="46%" cy="38%" r="65%"><stop stop-color="#272933"/><stop offset=".45" stop-color="#101118"/><stop offset=".73" stop-color="#0b0d12"/><stop offset=".9" stop-color="#232530"/><stop offset="1" stop-color="#080a0e"/></radialGradient><linearGradient id="camera-softbox" x2=".15" y2="1"><stop stop-color="#eff0f7" stop-opacity=".85"/><stop offset=".38" stop-color="#a0a4b6" stop-opacity=".54"/><stop offset="1" stop-color="#767b97" stop-opacity="0"/></linearGradient><linearGradient id="camera-flash" x2="0" y2="1"><stop stop-color="#eeeef6"/><stop offset=".55" stop-color="#8e91a2"/><stop offset="1" stop-color="#373945"/></linearGradient><filter id="camera-shadow" x="-25%" y="-25%" width="150%" height="160%"><feGaussianBlur stdDeviation="4"/></filter>'''
camera_body='''<rect x="28" y="55" width="200" height="154" rx="23" fill="url(#camera-body)" stroke="url(#camera-edge)" stroke-width="1.4"/><path d="M43 60q5-3 14-3h145q12 0 19 10" stroke="#b6b6c4" stroke-opacity=".14" stroke-width=".8"/><circle cx="128" cy="143" r="59" fill="#07080b" opacity=".65" filter="url(#camera-shadow)"/><circle cx="128" cy="134" r="60" fill="url(#camera-ring)" stroke="#92929e" stroke-opacity=".32" stroke-width=".8"/><circle cx="128" cy="134" r="44" fill="#101117" stroke="#777783" stroke-opacity=".4" stroke-width="1"/><circle cx="128" cy="134" r="40.5" fill="url(#camera-glass)" stroke="#353641" stroke-width=".7"/><circle cx="128" cy="134" r="35.5" stroke="#646375" stroke-opacity=".14" stroke-width=".7"/><circle cx="128" cy="134" r="28" stroke="#767287" stroke-opacity=".09" stroke-width=".5"/><path d="M104 114c1-17 45-21 48-2 1 7-7 13-24 13-14 0-25-4-24-11Z" fill="url(#camera-softbox)"/><path d="M104 162q24 15 47-3" stroke="#7c7496" stroke-opacity=".19" stroke-width="1.1"/><circle cx="128" cy="133" r="2.1" fill="#d7dbe5" opacity=".7"/><rect x="184" y="71" width="22" height="17" rx="3" fill="#17181e" stroke="#767780" stroke-opacity=".35"/><rect x="188" y="74" width="14" height="10" rx="1.8" fill="url(#camera-flash)"/><path d="M186 87h18" stroke="#979aa8" stroke-opacity=".28"/>'''
add('camera','A minimal rounded charcoal camera with a broad glass lens, restrained studio reflections, and a small inset flash, following the supplied reference.',camera_defs,camera_body)

material_defs='''<radialGradient id="material-satin" cx="32%" cy="24%" r="79%"><stop stop-color="#efebe0"/><stop offset=".25" stop-color="#d8d7d1"/><stop offset=".53" stop-color="#a4afb5"/><stop offset=".75" stop-color="#647885"/><stop offset=".93" stop-color="#354b5f"/><stop offset="1" stop-color="#66818e"/></radialGradient><radialGradient id="material-highlight" cx="37%" cy="28%" r="48%"><stop stop-color="#fffdf5" stop-opacity=".65"/><stop offset=".4" stop-color="#fffaf0" stop-opacity=".2"/><stop offset="1" stop-color="#f2efe4" stop-opacity="0"/></radialGradient><linearGradient id="material-rim" x2=".8" y2="1"><stop stop-color="#f7f3e7" stop-opacity=".8"/><stop offset=".45" stop-color="#9cbdc9" stop-opacity=".05"/><stop offset="1" stop-color="#9dbccc" stop-opacity=".5"/></linearGradient><clipPath id="material-clip"><circle cx="128" cy="125" r="79"/></clipPath>'''
material_body='<circle cx="128" cy="125" r="79" fill="url(#material-satin)"/><g clip-path="url(#material-clip)">'
# Seeded micro-pitting follows the sphere; no raster noise or baked texture.
rng=random.Random(85)
for i in range(1000):
    x,y=rng.uniform(-1,1),rng.uniform(-1,1)
    if x*x+y*y>.98:continue
    z=math.sqrt(1-x*x-y*y)
    r=rng.uniform(.18,.52)*(.4+.6*z)
    material_body+=f'<circle cx="{128+x*79:.2f}" cy="{125+y*79:.2f}" r="{r:.2f}" fill="{ "#ffffff" if i%3==0 else "#263d4b" }" opacity="{rng.uniform(.025,.12):.3f}"/>'
material_body+='''<circle cx="128" cy="125" r="79" fill="url(#material-highlight)"/><path d="M68 74C61 126 123 178 199 159" stroke="#223745" stroke-opacity=".38" stroke-width="2.1"/><path d="M67 75C60 128 123 180 199 161" stroke="#ebf0e9" stroke-opacity=".33" stroke-width=".8"/></g><circle cx="128" cy="125" r="79" stroke="url(#material-rim)" stroke-width=".8"/>'''
add('material','A satin ceramic material sample: pearl-gray shading, broad roughness-controlled highlights, fine surface micro-pitting, a recessed shader-ball seam, and a cool edge reflection. No chrome bands.',material_defs,material_body)
